using Captovix;
using System.Text.Json;
var count=0;
void Check(bool value,string message){if(!value)throw new Exception(message);count++;Console.WriteLine("PASS: "+message);}
void Reject(Action action,string message){try{action();}catch{Check(true,message);return;}Check(false,message);}
var root=Path.Combine(Path.GetTempPath(),"Captovix-reliability-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
try{
 for(int direction=0;direction<9;direction++){var offset=StudioStyle.Offset(direction,13);Check(offset.X==(direction%3-1)*13&&offset.Y==(direction/3-1)*13,"Shadow direction "+direction);}
 Check(StudioStyle.Offset(7,8)==(0d,8d),"Bottom middle is straight down");Check(StudioStyle.Offset(4,8)==(0d,0d),"Center is surrounding halo");
 Reject(()=>StudioStyle.Offset(9,2),"Reject invalid direction");Reject(()=>StudioStyle.Offset(7,double.NaN),"Reject nonfinite distance");
 var shape=new Annotation{Kind=AnnotationKind.RoundedRectangle,X1=20,Y1=30,X2=120,Y2=100,FillEnabled=true,FillColor="#D4E5FC",Dash=StrokePattern.Dash,Shadow=new(){Enabled=true,Direction=7}};
 var copy=shape.Copy();copy.Shadow.Direction=0;Check(shape.Shadow.Direction==7,"Shadow copies are independent");
 var doc=new EditorDocument{OriginalWidth=200,OriginalHeight=200,Annotations=[shape]};doc.Validate(200,200,"");var round=EditorDocument.Deserialize(doc.Serialize());Check(round.Version==10&&round.Annotations[0].Shadow.Direction==7,"Schema10 preserves shadow");
 for(int version=1;version<10;version++){var old=EditorDocument.Deserialize(doc.Serialize().Replace("\"Version\": 10","\"Version\": "+version));old.Validate(200,200,"");Check(old.Version==10,"Migrate schema "+version);}
 var invalid=shape.Copy();invalid.Shadow.Opacity=101;Reject(()=>StudioStyle.Validate(invalid),"Reject invalid shadow opacity");invalid.Shadow= null!;Reject(()=>StudioStyle.Validate(invalid),"Reject null shadow");
 var id=StudioStyle.Signature(shape);var moved=shape.Copy();moved.Id="other";moved.X1=70;moved.Rotation=30;moved.Name="Name";moved.GroupId="group";Check(StudioStyle.Signature(moved)==id,"Favorites ignore object identity and placement");moved.FillColor="#FFFFFF";Check(StudioStyle.Signature(moved)!=id,"Favorites distinguish paint colors");
 var list=new List<StyleFavorite>{new(id,"Rounded",StudioStyle.Sample(shape))};StyleFavoriteStore.Save(root,list);var loaded=StyleFavoriteStore.Load(root,out var warning);Check(warning==null&&loaded.Count==1&&loaded[0].Style.Shadow.Enabled,"Favorite survives reopening");StyleFavoriteStore.Save(root,list);Check(File.Exists(StyleFavoriteStore.PathFor(root)+".pre-v1.11.1.bak"),"Favorite file backup before rewriting");
 Reject(()=>StyleFavoriteStore.Save(root,[list[0],list[0]]),"Reject duplicate favorite");File.WriteAllText(StyleFavoriteStore.PathFor(root),"broken");Check(StyleFavoriteStore.Load(root,out warning).Count==0&&warning!=null&&File.ReadAllText(StyleFavoriteStore.PathFor(root))=="broken","Corrupt favorites are not overwritten by load");
 var photo=new CapturePhotoStyle{BorderEnabled=true,BorderWidth=6,BorderColor="#123456"};photo.Validate();var photoCopy=JsonSerializer.Deserialize<CapturePhotoStyle>(JsonSerializer.Serialize(photo))!;Check(photoCopy.BorderEnabled&&photoCopy.BorderWidth==6&&photoCopy.BorderColor=="#123456","Capture border persists as extensible settings");photo.BorderWidth=0;Reject(photo.Validate,"Reject zero capture border width");photo.BorderWidth=6;photo.BorderColor="red";Reject(photo.Validate,"Require exact capture border color");
 Check(EditorViewportMath.Intent(false,false)==WheelIntent.VerticalScroll&&EditorViewportMath.Intent(false,true)==WheelIntent.HorizontalScroll&&EditorViewportMath.Intent(true,false)==WheelIntent.Zoom&&EditorViewportMath.Intent(true,true)==WheelIntent.Zoom,"Modifier routing: scroll vertical, Shift horizontal, Ctrl zoom");
 Check(EditorViewportMath.WheelOffset(100,120,500)==52&&EditorViewportMath.WheelOffset(100,-120,500)==148,"Wheel scrolls both directions at 48px per detent");Check(EditorViewportMath.WheelOffset(10,120,500)==0&&EditorViewportMath.WheelOffset(490,-120,500)==500,"Wheel clamps at viewport edges");Check(EditorViewportMath.WheelZoom(1,120)>1,"Ctrl wheel zoom math retained");
 var original=Path.Combine(root,"Media","image.png");var edit=Path.Combine(root,"Edits","image.json");Directory.CreateDirectory(Path.GetDirectoryName(original)!);Directory.CreateDirectory(Path.GetDirectoryName(edit)!);File.WriteAllBytes(original,[0,1,2,3]);File.WriteAllText(edit,"sidecar");var receipt=MediaTrash.Move(root,"metadata",[original,edit,original]);Check(!File.Exists(original)&&!File.Exists(edit)&&receipt.Entries.Count==2,"Delete moves original and sidecar once");Check(MediaTrash.Restore(receipt)=="metadata"&&File.ReadAllBytes(original).SequenceEqual(new byte[]{0,1,2,3})&&File.ReadAllText(edit)=="sidecar","Restore preserves exact original and edit bytes");
 MediaTrash.UndoRestore(receipt);Check(!File.Exists(original)&&receipt.Entries.All(e=>File.Exists(e.Stored)),"Store commit failure can roll restored files back into trash");MediaTrash.Restore(receipt);
 var receipt2=MediaTrash.Move(root,"metadata",[original,edit]);File.WriteAllText(original,"conflict");Reject(()=>MediaTrash.Restore(receipt2),"Restore refuses overwriting existing file");Check(receipt2.Entries.All(e=>File.Exists(e.Stored))&&!File.Exists(edit),"Restore conflict leaves trash untouched");
 Console.WriteLine($"{count} studio reliability checks passed.");
}finally{Directory.Delete(root,true);}
